  // a tube of 4 or 6 sides between two points (the towers' slanted legs and braces, the penstock)
  function tube(g, a, b, r, n, col) {
    const dx = b[0] - a[0], dy = b[1] - a[1], dz = b[2] - a[2], l = Math.hypot(dx, dy, dz) || 1, ux = dx / l, uy = dy / l, uz = dz / l;
    let px = -uz, py = 0, pz = ux; if (Math.hypot(px, pz) < 1e-3) { px = 1; pz = 0; } const pl = Math.hypot(px, py, pz); px /= pl; pz /= pl;
    const qx = uy * pz - uz * py, qy = uz * px - ux * pz, qz = ux * py - uy * px, inn = [(a[0] + b[0]) / 2, (a[1] + b[1]) / 2, (a[2] + b[2]) / 2];
    const ring = (o) => { const R = []; for (let k = 0; k < n; k++) { const t = (k + 0.5) / n * Math.PI * 2, c = Math.cos(t) * r, s = Math.sin(t) * r; R.push([o[0] + px * c + qx * s, o[1] + py * c + qy * s, o[2] + pz * c + qz * s]); } return R; };
    const A = ring(a), B = ring(b);
    for (let k = 0; k < n; k++) { const j = (k + 1) % n; g.quadO(A[k], B[k], B[j], A[j], col, inn); }
  }

