      let dx = 0, dz = 0; for (const [a, b] of SPANS) if (a === k || b === k) { const o = TOWERS[a === k ? b : a], s = a === k ? 1 : -1; const l = Math.hypot(o[0] - x, o[1] - z) || 1; dx += s * (o[0] - x) / l; dz += s * (o[1] - z) / l; }
